#!/usr/bin/env bash
#
# build-ssm-document.sh — generate ssm/configure-swap.yml from
# scripts/configure-swap.sh so the SSM document never drifts from the script.
#
# Usage:
#   ./scripts/build-ssm-document.sh          # (re)write ssm/configure-swap.yml
#   ./scripts/build-ssm-document.sh --check  # exit 1 if the committed file is stale (CI)

set -Eeuo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(dirname "$SCRIPT_DIR")"
SRC="${SCRIPT_DIR}/configure-swap.sh"
OUT="${REPO_ROOT}/ssm/configure-swap.yml"

render() {
  cat <<'EOF'
# GENERATED by scripts/build-ssm-document.sh from scripts/configure-swap.sh.
# Do not edit by hand: change the script and re-run `make ssm-doc`.
---
schemaVersion: "2.2"
description: >-
  Idempotently add a swap file and set vm.swappiness on Amazon Linux /
  RHEL-family / Ubuntu hosts. No reboot required. Safe to re-run.
parameters:
  SwapSizeMiB:
    type: String
    description: Swap file size in MiB.
    default: "8192"
    allowedPattern: "^[0-9]{3,6}$"
  Swappiness:
    type: String
    description: Value for vm.swappiness (0-200).
    default: "10"
    allowedPattern: "^([0-9]|[1-9][0-9]|1[0-9][0-9]|200)$"
mainSteps:
  - action: aws:runShellScript
    name: configureSwap
    precondition:
      StringEquals:
        - platformType
        - Linux
    inputs:
      timeoutSeconds: "1800"
      runCommand:
        - |
          export SWAP_SIZE_MIB='{{ SwapSizeMiB }}'
          export SWAPPINESS='{{ Swappiness }}'
          cat > /tmp/configure-swap.sh <<'SCRIPT'
EOF
  sed 's/^/          /; s/[[:space:]]*$//' "$SRC"
  cat <<'EOF'
          SCRIPT
          bash /tmp/configure-swap.sh
          rc=$?
          rm -f /tmp/configure-swap.sh
          exit $rc
EOF
}

if [[ "${1:-}" == "--check" ]]; then
  if diff -q <(render) "$OUT" >/dev/null 2>&1; then
    echo "ssm/configure-swap.yml is up to date"
  else
    echo "ssm/configure-swap.yml is stale — run 'make ssm-doc'" >&2
    exit 1
  fi
else
  render > "$OUT"
  echo "Wrote ${OUT}"
fi
